1	package entropy
2	
3	import (
4		"cmp"
5		"math"
6		"slices"
7	)
8	
9	// EntropyResult contains the results of entropy-based analysis
10	type EntropyResult struct {
11		Entropy           float64 // Shannon entropy of the probability distribution
12		NormalizedEntropy float64 // Entropy normalized to [0,1] range
13		Certainty         float64 // Inverse of normalized entropy (1 - normalized_entropy)
14		UncertaintyLevel  string  // Human-readable uncertainty level
15	}
16	
17	// CategoryProbability represents a category and its probability
18	type CategoryProbability struct {
19		Category    string  // Category name
20		Probability float32 // Probability for this category
21	}
22	
23	// CalculateEntropy calculates Shannon entropy from a probability distribution
24	func CalculateEntropy(probabilities []float32) float64 {
25		if len(probabilities) == 0 {
26			return 0.0
27		}
28	
29		entropy := 0.0
30		for _, prob := range probabilities {
31			if prob > 0 {
32				entropy -= float64(prob) * math.Log2(float64(prob))
33			}
34		}
35	
36		return entropy
37	}
38	
39	// CalculateNormalizedEntropy calculates normalized entropy (0 to 1 scale)
40	func CalculateNormalizedEntropy(probabilities []float32) float64 {
41		if len(probabilities) <= 1 {
42			return 0.0
43		}
44	
45		entropy := CalculateEntropy(probabilities)
46		maxEntropy := math.Log2(float64(len(probabilities)))
47	
48		if maxEntropy == 0 {
49			return 0.0
50		}
51	
52		return entropy / maxEntropy
53	}
54	
55	// AnalyzeEntropy performs comprehensive entropy analysis
56	func AnalyzeEntropy(probabilities []float32) EntropyResult {
57		entropy := CalculateEntropy(probabilities)
58		normalizedEntropy := CalculateNormalizedEntropy(probabilities)
59		certainty := 1.0 - normalizedEntropy
60	
61		// Determine uncertainty level
62		var uncertaintyLevel string
63		switch {
64		case normalizedEntropy >= 0.8:
65			uncertaintyLevel = "very_high"
66		case normalizedEntropy >= 0.6:
67			uncertaintyLevel = "high"
68		case normalizedEntropy >= 0.4:
69			uncertaintyLevel = "medium"
70		case normalizedEntropy >= 0.2:
71			uncertaintyLevel = "low"
72		default:
73			uncertaintyLevel = "very_low"
74		}
75	
76		return EntropyResult{
77			Entropy:           entropy,
78			NormalizedEntropy: normalizedEntropy,
79			Certainty:         certainty,
80			UncertaintyLevel:  uncertaintyLevel,
81		}
82	}
83	
84	// ReasoningDecision contains the result of entropy-based reasoning decision
85	type ReasoningDecision struct {
86		UseReasoning     bool                  // Whether to use reasoning
87		Confidence       float64               // Confidence in the decision
88		DecisionReason   string                // Human-readable reason for the decision
89		FallbackStrategy string                // Strategy used for uncertain cases
90		TopCategories    []CategoryProbability // Top predicted categories
91	}
92	
93	// MakeEntropyBasedReasoningDecision implements the entropy-based reasoning strategy
94	func MakeEntropyBasedReasoningDecision(
95		probabilities []float32,
96		categoryNames []string,
97		categoryReasoningMap map[string]bool,
98		baseConfidenceThreshold float64,
99	) ReasoningDecision {
100		if len(probabilities) == 0 || len(categoryNames) == 0 {
101			return ReasoningDecision{
102				UseReasoning:     false,
103				Confidence:       0.0,
104				DecisionReason:   "no_classification_data",
105				FallbackStrategy: "default_no_reasoning",
106			}
107		}
108	
109		// Analyze entropy
110		entropyResult := AnalyzeEntropy(probabilities)
111	
112		// Get top predicted categories with probabilities
113		topCategories := getTopCategories(probabilities, categoryNames, 3)
114	
115		// Get the top prediction
116		topCategory := topCategories[0]
117		topConfidence := float64(topCategory.Probability)
118	
119		// Entropy-based decision logic
120		switch entropyResult.UncertaintyLevel {
121		case "very_high":
122			// Very uncertain - use conservative default (enable reasoning for safety)
123			return ReasoningDecision{
124				UseReasoning:     true,
125				Confidence:       0.3,
126				DecisionReason:   "very_high_uncertainty_conservative_default",
127				FallbackStrategy: "high_uncertainty_reasoning_enabled",
128				TopCategories:    topCategories,
129			}
130	
131		case "high":
132			// High uncertainty - use weighted decision from top 2 categories
133			topTwoCategories := topCategories
134			if len(topTwoCategories) > 2 {
135				topTwoCategories = topTwoCategories[:2]
136			}
137			decision := makeWeightedDecision(topTwoCategories, categoryReasoningMap, "high_uncertainty_weighted_decision")
138			decision.FallbackStrategy = "top_two_categories_weighted"
139			return decision
140	
141		case "medium":
142			// Medium uncertainty - trust top category if above threshold, otherwise weighted
143			if topConfidence >= baseConfidenceThreshold {
144				if useReasoning, exists := categoryReasoningMap[topCategory.Category]; exists {
145					return ReasoningDecision{
146						UseReasoning:     useReasoning,
147						Confidence:       topConfidence * 0.8, // Reduce confidence due to medium uncertainty
148						DecisionReason:   "medium_uncertainty_top_category_above_threshold",
149						FallbackStrategy: "trust_top_category",
150						TopCategories:    topCategories,
151					}
152				}
153			}
154	
155			// Fall back to weighted decision
156			return makeWeightedDecision(topCategories, categoryReasoningMap, "medium_uncertainty_weighted")
157	
158		case "low", "very_low":
159			// Low uncertainty - trust the classification completely
160			if useReasoning, exists := categoryReasoningMap[topCategory.Category]; exists {
161				confidenceMultiplier := 0.9
162				if entropyResult.UncertaintyLevel == "very_low" {
163					confidenceMultiplier = 0.95
164				}
165	
166				return ReasoningDecision{
167					UseReasoning:     useReasoning,
168					Confidence:       topConfidence * confidenceMultiplier,
169					DecisionReason:   entropyResult.UncertaintyLevel + "_uncertainty_trust_classification",
170					FallbackStrategy: "trust_top_category",
171					TopCategories:    topCategories,
172				}
173			}
174	
175			// Category not in reasoning map - default to no reasoning
176			return ReasoningDecision{
177				UseReasoning:     false,
178				Confidence:       topConfidence * 0.8,
179				DecisionReason:   "category_not_in_reasoning_map",
180				FallbackStrategy: "unknown_category_default",
181				TopCategories:    topCategories,
182			}
183	
184		default:
185			// Unknown uncertainty level - conservative default
186			return ReasoningDecision{
187				UseReasoning:     false,
188				Confidence:       0.5,
189				DecisionReason:   "unknown_uncertainty_level",
190				FallbackStrategy: "conservative_default",
191				TopCategories:    topCategories,
192			}
193		}
194	}
195	
196	// Helper function to get top N categories with their probabilities
197	func getTopCategories(probabilities []float32, categoryNames []string, topN int) []CategoryProbability {
198		if len(probabilities) != len(categoryNames) {
199			return []CategoryProbability{}
200		}
201	
202		// Create category-probability pairs
203		pairs := make([]CategoryProbability, len(probabilities))
