1	package classification
2	
3	import (
4		"sort"
5	
6		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
7	)
8	
9	func (c *KnowledgeBaseClassifier) computeLabelScores(queryEmb []float32) map[string]prototypeBankScore {
10		labelScores := make(map[string]prototypeBankScore, len(c.labels))
11		for labelName, data := range c.labels {
12			if data.Prototype == nil {
13				continue
14			}
15			labelScores[labelName] = data.Prototype.score(queryEmb, defaultPrototypeScoreOptions(c.rule.PrototypeScoring))
16		}
17		return labelScores
18	}
19	
20	func (c *KnowledgeBaseClassifier) effectiveThreshold(label string) float64 {
21		if threshold, ok := c.rule.LabelThresholds[label]; ok {
22			return float64(threshold)
23		}
24		return float64(c.rule.Threshold)
25	}
26	
27	func (c *KnowledgeBaseClassifier) buildMatchedLabels(labelScores map[string]float64) []string {
28		matched := make([]string, 0, len(labelScores))
29		for label, score := range labelScores {
30			if score >= c.effectiveThreshold(label) {
31				matched = append(matched, label)
32			}
33		}
34		sort.Strings(matched)
35		return matched
36	}
37	
38	func (c *KnowledgeBaseClassifier) computeGroupScores(labelScores map[string]float64) map[string]float64 {
39		groupScores := make(map[string]float64, len(c.rule.Groups))
40		for group, labels := range c.rule.Groups {
41			best := 0.0
42			for _, label := range labels {
43				if score := labelScores[label]; score > best {
44					best = score
45				}
46			}
47			groupScores[group] = best
48		}
49		return groupScores
50	}
51	
52	func (c *KnowledgeBaseClassifier) collectMatchedGroups(matchedLabels []string) []string {
53		if len(c.rule.Groups) == 0 || len(matchedLabels) == 0 {
54			return nil
55		}
56		labelSet := make(map[string]struct{}, len(matchedLabels))
57		for _, label := range matchedLabels {
58			labelSet[label] = struct{}{}
59		}
60		groups := make([]string, 0, len(c.rule.Groups))
61		for group, labels := range c.rule.Groups {
62			for _, label := range labels {
63				if _, ok := labelSet[label]; ok {
64					groups = append(groups, group)
65					break
66				}
67			}
68		}
69		sort.Strings(groups)
70		return groups
71	}
72	
73	func bestScoredName(scores map[string]float64) (string, float64) {
74		if len(scores) == 0 {
75			return "", 0
76		}
77		names := make([]string, 0, len(scores))
78		for name := range scores {
79			names = append(names, name)
80		}
81		sort.Strings(names)
82		bestName := ""
83		bestScore := 0.0
84		for _, name := range names {
85			score := scores[name]
86			if bestName == "" || score > bestScore {
87				bestName = name
88				bestScore = score
89			}
90		}
91		return bestName, bestScore
92	}
93	
94	func (c *KnowledgeBaseClassifier) computeMetricValues(labelScores, groupScores map[string]float64, bestScore, bestMatchedScore float64) map[string]float64 {
95		values := map[string]float64{
96			config.KBMetricBestScore:        bestScore,
97			config.KBMetricBestMatchedScore: bestMatchedScore,
98		}
99		for _, metric := range c.rule.Metrics {
100			if metric.Type != config.KBMetricTypeGroupMargin {
101				continue
102			}
103			values[metric.Name] = groupScores[metric.PositiveGroup] - groupScores[metric.NegativeGroup]
104		}
105		return values
106	}
107	
108	func (c *KnowledgeBaseClassifier) buildResultFromLabelScores(labelBankScores map[string]prototypeBankScore) *KBClassifyResult {
109		labelScores := make(map[string]float64, len(labelBankScores))
110		labelBestScores := make(map[string]float64, len(labelBankScores))
111		labelSupportScores := make(map[string]float64, len(labelBankScores))
112		for label, score := range labelBankScores {
113			labelScores[label] = score.Score
114			labelBestScores[label] = score.Best
115			labelSupportScores[label] = score.Support
116		}
117	
118		bestLabel, bestScore := bestScoredName(labelScores)
119		runnerUpScore := 0.0
120		if bestLabel != "" {
121			for label, score := range labelScores {
122				if label == bestLabel {
123					continue
124				}
125				if score > runnerUpScore {
126					runnerUpScore = score
127				}
128			}
129		}
130	
131		matchedLabels := c.buildMatchedLabels(labelScores)
132		matchedLabelScores := make(map[string]float64, len(matchedLabels))
133		for _, label := range matchedLabels {
134			matchedLabelScores[label] = labelScores[label]
135		}
136		bestMatchedLabel, bestMatchedScore := bestScoredName(matchedLabelScores)
137	
138		groupScores := c.computeGroupScores(labelScores)
139		bestGroup, _ := bestScoredName(groupScores)
140		matchedGroups := c.collectMatchedGroups(matchedLabels)
141		matchedGroupScores := make(map[string]float64, len(matchedGroups))
142		for _, group := range matchedGroups {
143			matchedGroupScores[group] = groupScores[group]
144		}
145		bestMatchedGroup, _ := bestScoredName(matchedGroupScores)
146	
147		return &KBClassifyResult{
148			BestLabel:             bestLabel,
149			BestSimilarity:        bestScore,
150			BestLabelMargin:       bestScore - runnerUpScore,
151			BestMatchedLabel:      bestMatchedLabel,
152			BestMatchedSimilarity: bestMatchedScore,
153			BestGroup:             bestGroup,
154			BestMatchedGroup:      bestMatchedGroup,
155			MatchedLabels:         matchedLabels,
156			MatchedGroups:         matchedGroups,
157			LabelConfidences:      labelScores,
158			LabelBestScores:       labelBestScores,
159			LabelSupportScores:    labelSupportScores,
160			GroupScores:           groupScores,
161			MetricValues:          c.computeMetricValues(labelScores, groupScores, bestScore, bestMatchedScore),
162		}
